# readrtdata
#' Read and load an annotated peak list from a file generated by external software.
#'
#' This function allows loading peaklists either from a data frame in R or from
#' a file in CSV, XLSX, or TXT format. The main parameter, data, accepts these two
#' options: a data frame containing lipid annotations or a file path pointing to
#' the peaklist. To ensure compatibility with different file formats, the function
#' also provides additional parameters such as sep, which specifies the character
#' used to separate columns (default is `,`), and dec.csv, which defines the decimal
#' separator in numeric data (default is `.`). These options guarantee that the peak
#' list is correctly interpreted and prepared for subsequent steps in the workflow.
#'
#' @param data data frame containing lipid annotations, which must include the
#' following columns: `mz` (mass-to-charge ratio), `RT` (retention time in seconds),
#' `lipidname` (lipid name or label), and `adduct` (ion adduct type). The lipid
#' identification column must be named either `LipidMSid` (if sourced from LipidMS),
#' `Metabolite name` (if sourced from MS-DIAL), or `lipidname` (if sourced from
#' another tool). Alternatively, this parameter can be a xlsx/csv/txt file containing
#' this information.
#' @param sep Character used to separate columns in text (.txt) or xlsx or CSV files. By default ",".
#' @param sheet Sheet to read. Either a string (the name of a sheet), or an integer
#' (the position of the sheet). Ignored if the sheet is specified via range.
#' If neither argument specifies the sheet, defaults to the first sheet.
#'
#' @details The input for this function consists of a peaklist of lipid annotations
#' provided in a tabular format. This table can be supplied as a CSV, XLSX, or TXT
#' file, or as a data frame directly in R. The peaklist may originate from different
#' lipid annotation software tools. Among these, LipidMS is supported, where the
#' equivalent input corresponds to the table found in msbatch$features or
#' msobject[[sample]]$annotation$annotatedPeaklist. Additionally, exported tables
#' from MS-DIAL or other tools following the short-hand annotation nomenclature
#' from LIPID MAPS (without detailed double bond information) are also accepted.
#' For inputs that do not originate from LipidMS or MS-DIAL, the table must
#' strictly include the following columns with these exact names: mz, RTsec or
#' RTmin, lipidname, adduct and confidencelevel. The column mz represents
#' the mass-to-charge ratio of the detected feature, while lipidname contains the
#' lipid annotation according to the short-hand nomenclature (e.g., PC(16:0/18:1), PC(34:1)).
#' The adduct column specifies the ion adduct type. Retention time (RT) must be
#' provided as either RTsec or RTmin, depending on whether the values are expressed
#' in seconds or minutes. Finally, the column confidencelevel is recommended to
#' indicate the reliability of the annotation. Accepted confidence levels follow
#' a hierarchical order from lowest to highest: MS-only, MSMS, Subclass, FA, and
#' FA position. If this column is missing, the workflow will attempt to infer the
#' confidence level from the lipid annotations during processing. These column
#' names are mandatory for proper function execution, and any deviation will prevent
#' the data from being correctly imported.
#'
#' Once the function has successfully executed it returns an object named `rtdata`.
#' This object is a structured list that organizes the imported data and subsequent
#' results. It contains a table called features (rtdata$features), which holds the
#' original peak list and will be progressively updated with new columns as filtering
#' and prediction steps are applied. It also includes a table named data (rtdata$data),
#' which stores the processed version of the peak list prepared for use in filtering
#' and prediction functions. Additionally, the object contains two lists: filtering
#' (rtdata$filtering) and prediction (rtdata$prediction). Initially, both lists are
#' empty and are progressively filled as the filtering and prediction steps are
#' performed. The filtering list stores all tables, intermediate results, and
#' outputs generated during the filtering process, while the prediction list
#' contains the tables and results produced during the RT prediction steps. This
#' structure ensures that all relevant information is systematically organized
#' and readily accessible throughout the workflow.
#'
#' @return rtdata
#'
#' @examples
#' \dontrun{
#' rtdata <- readrtdata(data = "file.csv", sep = ",")
#' }
#'
#' @author Celia Regal Marques <celia_regal@iislafe.es>
readrtdata <- function(data, sep = ",", sheet = NULL) {

  #============================================================================#
  # Read the input data: file (.txt, .csv, .xlsx) or data.frame
  #============================================================================#

  if (is.character(data)) {
    # Input is a file path
    extension <- tools::file_ext(data)

    # Detect source type and header row
    source_info <- checksource(features = data,
                               sep = sep,
                               sheet = sheet)
    source_data <- source_info$source_data
    header_row <- source_info$header_row

    # Read the file based on its extension
    features <- if (extension == "csv") {
      read.csv(data, header = TRUE, sep = sep, check.names = FALSE, skip = header_row-1)
    } else if (extension == "txt") {
      read.table(data, header = TRUE, sep = sep, check.names = FALSE, skip = header_row-1)
    } else if (extension == "xlsx") {
      readxl::read_excel(data, sheet = sheet, col_names = TRUE, skip = header_row-1,
                         guess_max = 500000)  # Increase guess_max for better type detection
    } else {
      stop("Unsupported file format. Please provide a .csv, .txt, or .xlsx file.\n")
    }

  } else if (is.data.frame(data)) {
    # Input is already a data.frame
    features <- data
    # Detect source type for the data.frame
    source_data <- checksource(features = data)

  } else {
    stop("Input 'data' must be a data.frame or a valid path to a .txt/.csv/.xlsx file.\n")
  }

  #============================================================================#
  # Clean and correct numeric columns depending on source type
  # Applies to both file input and data.frame input
  #============================================================================#

  # Ensure mz column exists
  mz_created <- FALSE
  if (!"mz" %in% colnames(features)) {
    features$mz <- NA_real_
    mz_created <- TRUE
  }


  if (source_data == "lipidms") {
    # Replace separators ";" with "|" for LipidMS specific columns
    features$LipidMSid <- gsub(";", "|", features$LipidMSid)
    features$Adduct <- gsub(";", "|", features$Adduct)
    features$confidenceLevel <- gsub(";", "|", features$confidenceLevel)
    features$Score <- gsub(";", "|", features$LipidMSid)
    features$ScoreInt <- gsub(";", "|", features$Adduct)
    features$nsamples <- gsub(";", "|", features$confidenceLevel)

    # Ensure mz and RT columns are numeric
    if (!is.numeric(features$mz) || !is.numeric(features$RT)) {
      features$mz <- as.numeric(gsub(",", ".", features$mz))
      features$RT <- as.numeric(gsub(",", ".", features$RT))
      if (!is.numeric(features$mz) || !is.numeric(features$RT)) {
        stop("The 'mz' or 'RT' columns are not numeric.\n")
      }
    }

  } else if (source_data == "msdial") {
    # Convert MS-DIAL columns to numeric if needed
    if (!is.numeric(features[["Average Mz"]]) || !is.numeric(features[["Average Rt(min)"]])) {
      features[["Average Mz"]] <- as.numeric(gsub(",", ".", features[["Average Mz"]]))
      features[["Average Rt(min)"]] <- as.numeric(gsub(",", ".", features[["Average Rt(min)"]]))
      if (!is.numeric(features[["Average Mz"]]) || !is.numeric(features[["Average Rt(min)"]])) {
        stop("The 'Average Mz' or 'Average Rt(min)' columns are not numeric.\n")
      }
    }

    # Assign column names from the detected header row (for MS-DIAL)
    colnames(features)[grep("^X1$|^X1\\.1$|^1$|^1\\.1$", colnames(features))] <-
      c("Average", "Stdev")

  } else if (source_data == "other") {
    # Lowercase version for matching
    cols_lower <- tolower(colnames(features))

    # Standardize RT column names if found
    if ("rtmin" %in% cols_lower) {
      colnames(features)[cols_lower == "rtmin"] <- "RTmin"
    }
    if ("rtsec" %in% cols_lower) {
      colnames(features)[cols_lower == "rtsec"] <- "RTsec"
    }

    # Handle other sources: find retention time columns
    rt_cols <- intersect(c("RTmin", "RTsec"), colnames(features))

    if (length(rt_cols) == 0) {
      stop("No retention time columns ('RTmin' or 'RTsec') found.\n")
    }

    # Convert RT columns to numeric
    for (col in rt_cols) {
      if (!is.numeric(features[[col]]) || any(grepl(",", features[[col]]))) {
        features[[col]] <- as.numeric(gsub(",", ".", features[[col]]))

        if (!is.numeric(features[[col]])) {
          stop(paste0("The retention time column '", col, "' is not numeric.\n"))
        }
      }
    }

    # Select main RT column (prioritize RTsec if present)
    rt_col <- if ("RTsec" %in% rt_cols) "RTsec" else "RTmin"

    # Standardize mz too
    cols_lower <- tolower(colnames(features))
    if ("mz" %in% cols_lower) {
      colnames(features)[cols_lower == "mz"] <- "mz"
    }

    # Convert mz column to numeric if exists
    if ("mz" %in% colnames(features)) {
      # if (!is.numeric(features$mz)) {
      #   features$mz <- as.numeric(gsub(",", ".", features$mz, fixed = TRUE))
      #
      #   if (!is.numeric(features$mz)) {
      #     stop("The 'mz' column is not numeric.\n")
      #   }
      # }
      mz_created <- FALSE

      # 1. Ensure mz exists
      if (!"mz" %in% colnames(features)) {
        features$mz <- NA_real_
        mz_created <- TRUE
      }

      # 2. Convert ONLY if needed and safe
      if (!is.numeric(features$mz)) {

        # Detect if there is at least one non-NA, non-empty value
        non_na_idx <- !is.na(features$mz) & features$mz != ""

        if (any(non_na_idx)) {

          mz_old <- features$mz

          # Convert only those entries
          converted <- as.numeric(gsub(",", ".", mz_old[non_na_idx], fixed = TRUE))

          # Check for real conversion errors
          if (any(is.na(converted))) {
            stop("Some values in 'mz' could not be converted to numeric.\n")
          }

          # Assign back safely
          features$mz <- NA_real_
          features$mz[non_na_idx] <- converted

        } else {
          # All values are NA or empty → just coerce safely
          features$mz <- as.numeric(NA_real_)
        }
      }

      # 3. Final check
      if (all(is.na(features$mz))) {

        if (mz_created) {
          warning("The 'mz' column did not exist and was created as NA.\n")
        } else {
          warning("The 'mz' column exists but contains only NA values.\n")
        }
      }

    }
  }

  #============================================================================#
  # Standardize annotated peak list
  #============================================================================#

  # Add 'LipidRTid' column if it does not exist
  if (!("LipidRTid" %in% colnames(features))) {
    features$LipidRTid <- seq_len(nrow(features))
  }

  # Extract individual annotations and standardize data
  data <- standardizedata(features = features,
                          source = source_data)

  #============================================================================#
  # Determine polarity of data
  #============================================================================#
  polarity <- determinepolarity(data)

  #============================================================================#
  # Create structured rtdata object
  #============================================================================#
  rtdata <- list(metadata = list(source = source_data,
                                 polarity = polarity,
                                 filtering = list(),
                                 prediction = list()),
                 features = features,
                 data = data,
                 filtering = list(),
                 prediction = list())

  return(rtdata)
}


# filterannotations
#' Filtering of annotated data based on RT criteria that allows discerning
#' erroneous annotations.
#'
#' Filtering of annotated data that allows discerning erroneous annotations.
#' The filtering is done in two phases. The first filter is based on the order
#' in which the different subclasses of lipids should elute during chromatography,
#' allowing the differentiation between correct annotations and those associated
#' with in-source fragments, eliminating the latter. After this, a second filter
#' will be applied, using the number of carbons and double bonds of the lipids
#' belonging to each class to check if the annotated species follow a pattern
#' consistent with their composition, eliminating those that do not.
#'
#' @param rtdata object resulting from `readrtdata` function.
#' @param isomeric_plasmalogens logical. If TRUE, alternative plasmalogen
#' annotations are proposed for features already annotated as plasmalogens
#' based on m/z matching. This is only appropriate when the annotation table
#' contains a single annotation per feature. If FALSE, no additional
#' plasmalogen annotations are proposed, which is recommended when multiple
#' annotations per feature are reported.
#' @param filedbs csv with subclasses to predict
#' @param sep Character. Field separator used when reading the CSV file.
#' @param adducts Data.frame. modify adductsTable.
#' @param dmz m/z tolerance in ppm or absolute mass error.
#' @param ppm logical. If TRUE, m/z tolerance in ppm. If FALSE, m/z tolerance in
#' absolute mass error.
#' @param distC_filter integer. Minimum difference in number of carbons from which lipids
#' are considered distant from the rest of lipids from the same class.
#' @param minSpecies_filter numeric. minimum number of carbons in a cluster from which
#' lipids are considered correct from the rest.
#' @param distribution character. Data distribution for RT modelling. It can be
#' "gamma" or "normal".
#' @param rtscorethr numeric. Minimum Score_rtpred value from which previously
#' filtered lipids will be recovered by the model.
#' @param rttol_id Numeric. Maximum allowed retention-time difference (in
#' seconds) to consider two observations part of the same group.
#' @param rttol_name Numeric. Maximum allowed retention-time difference (in
#' seconds) to consider two lipids as temporally close.
#' @param filter_plot logical. If TRUE, filtering results are plotted.
#' @param verbose logical. Print information messages.
#'
#' @details Once the peak list has been read using the `readrtdata` function and
#' the corresponding `rtdata` object has been generated, the peak list can be
#' filtered and new annotations can be predicted. To retain only high-confidence
#' annotations that follow the expected elution pattern, the filterannotations
#' function is applied. This function integrates a set of internal routines designed
#' to remove lipid annotations that do not comply with the expected intra-class
#' and inter-class elution order, based on a series of predefined rules and criteria.
#' To allow flexibility and user control, several parameters can be adjusted,
#' enabling filtering to be tailored to specific analytical requirements.
#'
#' The filtering procedure is performed sequentially. First, for features
#' associated with multiple annotations, those with lower confidence levels are
#' discarded, retaining only the most reliable annotation. Second, in-source fragments
#' corresponding to the MG, DG, LPL, and FA subclasses are removed. Third, outliers
#' within each lipid class are identified and eliminated based on the number of
#' carbon atoms, removing compounds that deviate markedly from their homologous
#' series and from the overall behavior of the class. The fourth step aims to
#' improve plasmalogen annotation. To this end, a priority order among subsubclasses
#' is defined (diacyl > alkenyl > alkanyl), such that when lipids with identical
#' compositions are detected, annotations are retained according to this hierarchy
#' and their consistency with the expected RT order, while lower-priority annotations
#' are removed. Next, lipids that do not follow the expected RT elution order within
#' their respective class are removed using an additional set of class-specific rules.
#' Finally, RT-based outliers are identified and eliminated, discarding lipids whose
#' retention behavior deviates substantially from the characteristic pattern of their class.
#'
#' After completion of the filtering process, the retained lipids, considered to
#' be of high confidence, are used to build predictive models of RT. These models
#' are then applied to predict the RTs of all lipids originally present in the
#' peak list and to compute a prediction score (Equation 3). Lipids with prediction
#' scores exceeding a defined threshold are recovered, even if they were removed
#' during earlier filtering steps, as they are considered to follow the expected
#' elution order according to the predictive model. The model incorporates variables
#' related to carbon number, degree of unsaturation, and a smoothing term, which can
#' introduce local curvature. At the lower end of the carbon range, this may produce
#' an artificial decrease in retention times with increasing carbon number, while
#' at the upper end, predicted times may decrease after a local maximum-both
#' behaviors do not follow the theoretically expected elution pattern. To correct
#' this, retention times for lipids below a local minimum are adjusted to follow a
#' monotonic increasing slope based on the difference between the minimum and the
#' preceding lipid, while for lipids above a local maximum, retention times are
#' capped at the value of the maximum. These adjustments ensure that predicted
#' retention times increase consistently with carbon number and degree of
#' unsaturation while preserving the overall structure of the predictive model.
#'
#' The input of the function is the `rtdata` object. In addition, the function
#' includes the parameters distC, minSpecies_filter, distribution, rtscorethr, filter_plot,
#' and verbose. The distC parameter (default is 5) defines the maximum allowed
#' distance, in number of carbon atoms, from the homologous series corresponding
#' to a given number of double bonds within a lipid class, beyond which a lipid
#' is considered a potential outlier. The minSpecies_filter parameter (default is 5)
#' specifies the minimum number of such distant lipids required to apply the
#' carbon-based filtering. Only when the number of lipids exceeding the distC
#' threshold is equal to or less than minSpecies_filter are they removed as outliers;
#' otherwise, this filtering step is not applied. In addition, the function provides
#' several parameters related to the generation of RT models at the end of the
#' filtering process, with the aim of automatically recovering lipids that may
#' have been erroneously removed during automatic filtering. The distribution
#' parameter (default is `gamma`) defines the statistical distribution used to
#' model RT and can take the values `gamma` or `normal`. The rtscorethr parameter
#' (default is `0.5`) defines the prediction score threshold above which previously
#' removed lipids are recovered. Furthermore, the filter_plot parameter (default is
#' TRUE) allows the user to choose whether to generate graphical representations of
#' the automatic filtering process. When enabled, two plots are generated: one
#' displaying the complete dataset, highlighting retained lipids, the RT model,
#' and lipids removed by the automatic filtering rules; and a second plot showing
#' only the lipids retained after filtering. If filter_plot is set to FALSE, these
#' plots are not generated. Finally, the verbose parameter (default = TRUE) controls
#' the console output, such that upon completion of the function execution, a
#' detailed summary of the filtering applied to each lipid class is displayed;
#' when set to FALSE, no text output is printed to the console.
#'
#' After filtering, all relevant information is stored within the `rtdata` object.
#' The peak list (rtdata$features) is updated with six new columns: filter_label,
#' which indicates the reason a lipid was removed; lipidname_filter, listing the
#' lipids retained after filtering; adduct_filter, specifying the adducts of the
#' retained lipids; confidenceLevel_filter, providing the confidence level of the
#' retained lipids; and Score_filter, showing the prediction score obtained for
#' the retained lipids following RT modeling. All columns maintain the same order
#' as the original peak list annotations. In addition, all tables and results
#' generated during the filtering process are stored in the filtering list
#' (rtdata$filtering). Within this list, data (rtdata$filtering$data) contains
#' the results of the automatic filtering; predictions (rtdata$filtering$predictions)
#' includes the RT modeling results and predictions for all annotated lipids;
#' rtpred_max (rtdata$filtering$rtpred_max), which contains information on local
#' maxima for the lipid subclasses where they are present; rtpred_min
#' (rtdata$filtering$rtpred_min), which contains information on local minima for
#' the lipid subclasses where they are present; information (rtdata$filtering$information)
#' provides a summary table of lipids retained and removed for each class in the
#' peak list, and models (rtdata$filtering$models) stores the RT models for each
#' lipid class. Finally, if filter_plot is set to TRUE, the plots list
#' (rtdata$filtering$plots) contains the filtering plots for each lipid class.
#'
#' @return rtdata
#'
#' @examples
#' \dontrun{
#' rtdata <- filterannotations(rtdata)
#' }
#'
#' @author Celia Regal Marques <celia_regal@iislafe.es>
filterannotations <- function(rtdata,
                              isomeric_plasmalogens = FALSE,
                              filedbs = NULL,
                              sep = ",",
                              adducts = NULL,
                              dmz = 5,
                              ppm = TRUE,
                              distC_filter = 5,
                              minSpecies_filter = 5,
                              distribution = "gamma",
                              rtscorethr = 0.5,
                              rttol_id = 5,
                              rttol_name = 1,
                              filter_plot = TRUE,
                              verbose = TRUE) {

  #============================================================================#
  # Check the structure of the input data
  #============================================================================#
  ##############################################################################
  data_structure <- checkdatastructure(rtdata)
  if (data_structure$structure != "rtdata") {
    stop(data_structure$message)
  }

  #==========================================================================#
  # Remove the previous filtering
  #==========================================================================#
  ############################################################################
  # If the data had already been filtered, remove previous filtering
  if ("lipidname_filter" %in% colnames(rtdata$features)) {
    rtdata <- removepreviousanalysis(rtdata = rtdata,
                                     typeanalysis = "filtering")
  }

  #============================================================================#
  # Check polarity
  #============================================================================#
  ##############################################################################
  polarity <- rtdata$metadata$polarity
  if (polarity == "both") {
    warning(
      paste(
        "Adducts must correspond to either positive or negative polarity only.\n",
        "Please ensure all adducts belong to a single polarity group.\n",
        "\n - The filtering procedure will be applied across polarities simultaneously.
        Nevertheless, retention time differences between polarity modes may compromise
        filtering performance. For optimal results, positive and negative polarity
        data should be processed independently.\n"
      )
    )

  }

  if (isomeric_plasmalogens) {
    #============================================================================#
    # Propose isobaric plasmalogens candidates
    #============================================================================#
    ##############################################################################
    rtdata <- proposemzcandidates(rtdata = rtdata,
                                  filedbs = filedbs,
                                  sep = sep,
                                  classes = NULL,
                                  adducts = adducts,
                                  dmz = dmz,
                                  ppm = ppm)
  }


  #============================================================================#
  # Filtering
  #============================================================================#
  ##############################################################################
  rtdata <- filterannotationsdata(rtdata = rtdata,
                                  distC_filter = distC_filter,
                                  minSpecies_filter = minSpecies_filter,
                                  distribution = distribution,
                                  rtscorethr = rtscorethr,
                                  rttol_id = rttol_id,
                                  rttol_name = rttol_name,
                                  filter_plot = filter_plot)

  #============================================================================#
  # Organize and save results
  #============================================================================#
  rtdata <- organizertdata(rtdata = rtdata,
                           typeanalysis = "filtering")

  #============================================================================#
  # Display results on screen
  #============================================================================#
  ##############################################################################
  if (verbose) {
    printfilteringinfo(rtdata)
  }

  return(rtdata)
}

# rtpredictannotations
#' Retention time modeling to propose new identifications for the features
#'
#' Retention time modeling to propose new identifications for the features.
#' New identifications are suggested for features that have not been previously
#' annotated, using potential candidates selected based on the m/z value.
#' Once potential candidates for the features are obtained, retention time is
#' modeled for each lipid class using previous annotations. Subsequently,
#' retention time is predicted for each candidate.
#'
#' @param rtdata filtered rtdata object obtained from `readrtdata` or
#' `filterannotations` function.
#' @param distribution character. Data distribution for RT modelling. It can be
#' "gamma" or "normal".
#' @param subclasses A vector containing the lipid subclasses for which retention time
#' is to be predicted. If subclasses = NULL, predictions will be made for all subclasses
#' where there are candidates and data to create a model.
#' @param filedbs csv with subclasses to predict
#' @param sep Character. Field separator used when reading the CSV file.
#' @param adducts Data.frame. modify adductsTable.
#' @param dmz m/z tolerance in ppm or absolute mass error.
#' @param ppm logical. If TRUE, m/z tolerance in ppm. If FALSE, m/z tolerance in
#' absolute mass error.
#' @param rtscorethr Minimum Score_rtpred value from which a prediction will be
#' considered valid.
#' @param distC_predict integer. Minimum difference in number of carbons from which lipids
#' are considered distant from the rest of lipids from the same class.
#' @param minSpecies_predict numeric. Minimum number of carbon units from any valid model
#' data or prediction beyond which predictions will be discarded. This value must
#' be at least 3, with a default of 5.
#' @param rt_thr numeric. Threshold for the difference (in seconds) between the
#' observed retention time (RT) and the predicted retention time (RT_rtpred). 30 seconds by default.
#' @param rttol_id Numeric. Maximum allowed retention-time difference (in
#' seconds) to consider two observations part of the same group.
#' @param rttol_name Numeric. Maximum allowed retention-time difference (in
#' seconds) to consider two lipids as temporally close.
#' @param predict_plot logical. If TRUE, predictions are plotted. If FALSE,
#' predictions are not plotted.
#' @param verbose logical. Print information messages
#'
#' @details Once the peak list has been filtered, new annotations can be proposed
#' based on m/z values for features that were initially unannotated or for which
#' all annotations were removed during the filtering process. For each candidate,
#' a prediction score is calculated, and those candidates with a prediction score
#' exceeding a user-defined threshold are proposed as new annotations. This procedure
#' is implemented through the rtpredictannotations function. Since RT modeling
#' requires high-confidence data, the method relies on a previously filtered peak
#' list. If the peak list has not been filtered beforehand, the filtering step is
#' performed automatically using default parameter values prior to RT modeling
#' and annotation prediction.
#'
#' The input of the function is the `rtdata` object. In addition, the function
#' includes the parameters dmz, ppm, distribution, rtscorethr, minSpecies_predict, rt_thr,
#' subclasses, filedbs, sep, sep_adduct, sep_chains, predict_plot, and verbose. In the
#' first step of the function, candidate annotations are proposed for individual
#' features based on their m/z values. This step is controlled by the dmz parameter
#' (default is 5), which defines the m/z tolerance used for candidate generation.
#' The tolerance can be interpreted either in parts per million (ppm) or as an
#' absolute mass error, depending on the ppm parameter (default is TRUE), which
#' specifies whether the tolerance is applied in ppm (TRUE) or in absolute units
#' (FALSE). After candidate generation, RT models are built for the different lipid
#' subclasses. For this step, the distribution parameter (default is "gamma") defines
#' the statistical distribution used to model RT and can take the values "gamma"
#' or "normal". The rtscorethr parameter (default is 0.5) defines the prediction
#' score threshold above which candidate annotations are accepted. The minSpecies_predict
#' parameter (default is 5) is used to remove proposed candidates that deviate
#' excessively in terms of carbon number within their corresponding double-bond
#' series, discarding those that are farther than the specified threshold, the
#' minimum allowed value is 3; if the user selects a lower number of carbons,
#' it will be automatically set to 3. In addition, the rt_thr parameter (default
#' is 30 seconds) allows labeling candidates that do not exceed the prediction
#' score threshold but whose difference between observed and predicted RT is
#' smaller than this secondary threshold as `discarded candidates`. These discarded
#' candidates can be manually recovered at a later stage through the package's
#' Shiny application using interactive plots. Candidates whose RT deviation exceeds
#' the rt_thr threshold are permanently rejected and cannot be recovered.
#'
#' The function also allows users to specify the lipid subclasses for which RT modeling
#' and annotation prediction should be performed. This is controlled by the subclasses
#' parameter (default is NULL), in which case candidates are proposed for all default
#' lipid subclasses using their default adducts and chains. When a vector of subclasses
#' is provided, candidate annotations are generated only for the selected subclasses
#' and their default adducts and chains, without allowing the inclusion of additional
#' subclasses beyond those defined by default. To modify the adducts used
#' for candidate generation, a CSV file can be provided via the filedbs parameter
#' (default is NULL).  This file must contain several columns describing, for each
#' lipid class (with the class specified in the subclasses column), both the adducts
#' considered and the structural information of the chains that may compose it.
#' With respect to adducts, the file may include one or two specific columns
#' depending on the polarity of the analysis. These columns are named adducts_pos
#' and adducts_neg and contain, respectively, the adducts to be considered in
#' positive and negative mode. Within each of these columns, the adducts corresponding
#' to a given lipid class must be listed in a single cell and separated using the
#' character defined by the sep_adducts parameter (default is ";"). During the
#' analysis, the adducts_pos column is automatically used if the user sets the
#' polarity to positive, whereas the adducts_neg column is used if the polarity
#' is set to negative. Although both adducts_pos and adducts_neg columns can be
#' included in the same file, the file may also contain only one of them, provided
#' that it is consistent with the polarity selected by the user. In addition to
#' the information related to adducts, the file must include columns describing
#' the possible lipid chains associated with each class. These columns are fas,
#' indicating fatty acids; sph, indicating the sphingoid base; alkyl, indicating
#' alkyl chains; and vinyl, indicating vinyl chains , with the default values for
#' each provided in Table S3. Depending on the structure of the lipid class
#' corresponding to each row, only the relevant columns need to be filled, while
#' the others may be left empty. The different values within each of these columns
#' must be separated using the character defined by the sep_chains parameter
#' (default is ";"). This parameter is subsequently used to separate the chains
#' and generate candidates during the prediction process.
#'
#' Finally, the predict_plot parameter (default is TRUE) allows the user to control
#' whether prediction plots are generated. When enabled, one set of plots is
#' generated for each lipid class for which new annotations are proposed. These
#' include: (i) a plot showing the RT model for the class together with the
#' high-confidence lipids used to build the model; (ii) a plot displaying the
#' data used for modeling alongside newly proposed annotations and discarded
#' candidates; and (iii) a plot showing only the retained high-confidence lipids
#' and the newly proposed annotations. When predict_plot is set to FALSE, no plots
#' are generated. The verbose parameter (default is TRUE) controls the console
#' output, such that upon completion of the function execution, a detailed summary
#' of the prediction results for each lipid class is displayed; when set to FALSE,
#' no text output is printed to the console.
#'
#' Using this function, predictive models of retention time are generated based
#' on the parameters selected by the user, including carbon number, degree of
#' unsaturation, and smoothing terms. Similar to the filtering step, when these
#' variables are included, the model may exhibit local curvature, which can produce
#' deviations from the theoretically expected elution pattern. At the lower end
#' of the carbon number range for a given lipid class, this can result in an
#' artificial decrease in predicted retention times, while at the upper end,
#' retention times may decrease after a local maximum. To address these effects,
#' predicted retention times for lipids below a local minimum are adjusted to
#' follow a monotonic increasing slope, while retention times for lipids above a
#' local maximum are capped at the value of the maximum. These adjustments ensure
#' that retention times increase consistently with carbon number and degree of
#' unsaturation while maintaining the overall predictive structure of the model.
#'
#' After modeling and predicting the RT of candidate lipids, the results are
#' stored in the `rtdata` object. The peak list (rtdata$features) is updated with
#' five new columns: lipidname_rtpred, which indicates the proposed candidate as
#' a new annotation; adduct_rtpred, specifying the corresponding adduct;
#' confidenceLevel_rtpred, which in this case is `Predicted` for all new proposed
#' annotations; RTsec_rtpred, containing the predicted RT; and Score_rtpred,
#' representing the prediction score for each new proposed annotations. Additionally,
#' three integrative columns are created to combine filtering and prediction results:
#' lipidname_final, which includes both retained annotations and newly proposed ones;
#' adduct_final, listing the corresponding adducts; and confidenceLevel_final,
#' indicating the confidence level. All tables and results generated during the
#' RT prediction process are stored in the rtdata$prediction list. This includes:
#' candidates (rtdata$prediction$candidates), which contains the results of the
#' automatic RT prediction; predictions (rtdata$prediction$predictions), comprising
#' RT predictions for all proposed lipids; rtpred_max (rtdata$prediction$rtpred_max),
#' which contains information on local maxima for the lipid subclasses where they are
#' present; rtpred_min (rtdata$prediction$rtpred_min), which contains information
#' on local minima for the lipid subclasses where they are present; information
#' (rtdata$prediction$information), summarizing newly proposed lipids and the
#' total number of lipids per class in the peak list; and models (rtdata$prediction$models),
#' which stores the RT models for each lipid class. Finally, if the parameter
#' predict_plot is set to TRUE, the plots list (rtdata$prediction$plots) includes
#' prediction plots.
#'
#' @return rtdata
#'
#' @examples
#' \dontrun{
#' rtdata <- rtpredictannotations(rtdata)
#' }
#'
#' @author Celia Regal Marques <celia_regal@iislafe.es>
rtpredictannotations <- function(rtdata,
                                 distribution = "gamma",
                                 subclasses = NULL,
                                 filedbs = NULL,
                                 sep = ",",
                                 adducts = NULL,
                                 dmz = 5,
                                 ppm = TRUE,
                                 rtscorethr = 0.5,
                                 distC_predict = 5,
                                 minSpecies_predict = 5,
                                 rt_thr = 30,
                                 rttol_id = 5,
                                 rttol_name = 1,
                                 predict_plot = TRUE,
                                 verbose = TRUE){

  #============================================================================#
  # Check the structure of the input data
  #============================================================================#
  ##############################################################################
  data_structure <- checkdatastructure(rtdata)
  if (data_structure$structure != "rtdata") {
    stop(data_structure$message)
  }

  #============================================================================#
  # Remove the previous predictions
  #============================================================================#
  ##############################################################################
  # If the data had already been predicted, remove previous predictions
  if (("lipidname_rtpred" %in% colnames(rtdata$features))) {
    rtdata <- removepreviousanalysis(rtdata = rtdata,
                                     typeanalysis = "prediction")
  }

  #============================================================================#
  # Check if the data is filtered, if not perform the filtering
  #============================================================================#
  ##############################################################################
  # If the data has not been filtered, perform the filtering
  if (!("lipidname_filter" %in% colnames(rtdata$features))) {
    warning("Filtering lipid annotations based on RT criteria (filterannotations() function)\n")
    rtdata <- filterannotations(rtdata)
  }

  #============================================================================#
  # Check polarity
  #============================================================================#
  ##############################################################################
  polarity <- rtdata$metadata$polarity
  if (is.null(polarity)) {
    warning(
      paste(
        "Adducts must correspond to either positive or negative polarity only.\n",
        "Please ensure all adducts belong to a single polarity group.\n",
        "\n - No valid polarity could be determined. Consequently, no candidate
        lipids will be proposed and retention time predictions will not be performed.\n"
      )
    )
  }

  #============================================================================#
  # Search for potential candidates
  #============================================================================#
  ##############################################################################
  # Search for potential candidates for the unannotated features
  rtdata <- proposertcandidates(rtdata = rtdata,
                                filedbs = filedbs,
                                sep = sep,
                                classes = subclasses,
                                adducts = adducts,
                                dmz = dmz,
                                ppm = ppm)

  #============================================================================#
  # RT predict
  #============================================================================#
  ##############################################################################
  rtdata <- rtpredictannotationsdata(rtdata = rtdata,
                                     distribution = distribution,
                                     classes = subclasses,
                                     rtscorethr = rtscorethr,
                                     distC_predict = distC_predict,
                                     minSpecies_predict = minSpecies_predict,
                                     rt_thr = rt_thr,
                                     rttol_id = rttol_id,
                                     rttol_name = rttol_name,
                                     predict_plot = predict_plot)

  #============================================================================#
  # Organize and save results
  #============================================================================#
  ##############################################################################
  rtdata <- organizertdata(rtdata = rtdata,
                           typeanalysis = "prediction")

  #============================================================================#
  # Display results on screen
  #============================================================================#
  ##############################################################################
  if (verbose) {
    printpredictioninfo(rtdata)
  }

  return(rtdata)
}



# rttargetpredict
#' Targeted retention time prediction for lipid subclasses
#'
#' Performs a targeted retention time prediction for lipid subclasses that can be
#' modeled based on existing annotations. A retention time model is built for
#' each lipid class, and retention times are predicted for the corresponding
#' lipid candidates, similarly to a targeted prediction approach. The function
#' returns a table containing the predicted retention times together with their
#' confidence intervals.
#'
#' @param rtdata rtdata object.
#' @param path Character string indicating the path to save the table as a CSV file.
#' If `NULL` (default), the table is not saved.
#'
#' @return predictions
#'
#' @examples
#' \dontrun{
#' predictions <- rttargetpredict(rtdata)
#' }
#'
#' @author Celia Regal Marques <celia_regal@iislafe.es>
rttargetpredict <- function(rtdata, path = NULL) {

  #============================================================================#
  # Check the structure of the input data
  #============================================================================#
  ##############################################################################
  data_structure <- checkdatastructure(rtdata)
  if (data_structure$structure != "rtdata") {
    stop(data_structure$message)
  }

  #============================================================================#
  # Check if the data is predicted, if not perform the prediction
  #============================================================================#
  ##############################################################################
  # If the data has not been filtered, perform the filtering
  if (!("lipidname_filter" %in% colnames(rtdata$features))) {
    warning("Predicting retention times using 'rtpredictannotations()'\n")
    rtdata <- rtpredictannotations(rtdata)
  }

  #============================================================================#
  # Targeted predictions data frame
  #============================================================================#
  ##############################################################################
  if (!is.null(rtdata$prediction$predictions) &&
      nrow(rtdata$prediction$predictions) != 0) {
    predictions <- targetpredictions(predictions = rtdata$prediction$predictions)

    if (is.null(path)) {

    } else if (is.character(path)) {

      # Ensure the directory exists
      dir <- dirname(path)
      if (!dir.exists(dir)) {
        dir.create(dir, recursive = TRUE, showWarnings = FALSE)
      }

      # Force .csv extension if missing
      if (!grepl("\\.csv$", path, ignore.case = TRUE)) {
        path <- paste0(path, ".csv")
      }

      # Write CSV
      tryCatch({
        utils::write.csv(predictions, file = path, row.names = FALSE)
      }, error = function(e) {
        warning("Could not save predictions CSV at the provided path: ", e$message)
      })

    } else {

      warning("Parameter 'path' must be a valid file path as a character string where the targeted predictions CSV will be saved.\n")
    }

  } else {
    predictions <- data.frame(lipidname = character(0),
                              RTsec_rtpred = double(0),
                              CI_lower = double(0),
                              CI_upper = double(0))

    warning("No retention time predictions were generated. Therefore, no results are available to display or export.\n")
  }

  return(predictions)

}


# modelreport
#' Generate a detailed report summarizing the results of RT-based lipid analysis.
#'
#' This function creates a textual report describing the outcome of the lipid
#' filtering and/or RT prediction process. The report includes global feature
#' statistics (annotated vs non-annotated features), results after filtering
#' and/or prediction steps, and a detailed summary of the RT models built for
#' each lipid class, including model summaries and performance metrics.
#'
#' @param rtdata rtdata object from filterannotations or rtpredictannotations functions.
#' @param typeanalysis Character. Specifies whether the function is being used for
#' filtering or RT predictions. Possible values are "filtering" or "prediction".
#' @param file_path Character. Optional path to a file where the report will be
#' saved. If NULL, the report is returned as a character string.
#'
#' @return report
#'
#' @examples
#' \dontrun{
#' report <- modelreport(rtdata, typeanalysis = "filtering")
#' }
#'
#' @author Celia Regal Marques <celia_regal@iislafe.es>
modelreport <- function(rtdata, typeanalysis, file_path = NULL) {
  report <- ""

  report <- paste0(report,
                   "\n =================================================================",
                   "\n|----------------------------------------------------------------\n|","\n",
                   "| Analysis:       ", typeanalysis, "\n",
                   "|-----------------------------------------------------------------\n|",
                   "\n|  - Total features in data ", nrow(rtdata$features),
                   "\n|      - Annotated features ", nrow(rtdata$features[rtdata$features$LipidMSid != "", ]),
                   "\n|      - Non-annotated features ", nrow(rtdata$features[rtdata$features$LipidMSid == "", ]), "\n|")



  if (typeanalysis == "filtering") {
    models <- rtdata$filtering$models

    report <- paste0(report,
                     "\n|-----------------------------------------------------------------\n|",
                     "\n|      - Filtered features ", nrow(rtdata$features[rtdata$features$LipidMSid != "", ]) - nrow(rtdata$features[rtdata$features$lipidname_filter != "", ]),
                     "\n|      - Annotated features after filtering ", nrow(rtdata$features[rtdata$features$lipidname_filter != "", ]),
                     "\n|      - Non-annotated features after filtering ", nrow(rtdata$features[rtdata$features$lipidname_filter == "", ]),"\n|",
                     "\n|-----------------------------------------------------------------\n",
                     " =================================================================\n"
    )
  } else if (typeanalysis == "prediction") {
    models <- rtdata$prediction$models
    report <- paste0(report,
                     "\n|-----------------------------------------------------------------\n|",
                     "\n|      - Filtered features ", nrow(rtdata$features[rtdata$features$LipidMSid != "", ]) - nrow(rtdata$features[rtdata$features$lipidname_filter != "", ]),
                     "\n|      - Annotated features after filtering ", nrow(rtdata$features[rtdata$features$lipidname_filter != "", ]),
                     "\n|      - Non-annotated features after filtering ", nrow(rtdata$features[rtdata$features$lipidname_filter == "", ]),
                     "\n|----------------------------------------------------------------\n|",
                     "\n|      - Predicted features ", nrow(rtdata$features[rtdata$features$lipidname_rtpred != "", ]),
                     "\n|      - Annotated features after prediction ", nrow(rtdata$features[rtdata$features$lipidname_final != "", ]),
                     "\n|      - Non-annotated features after prediction ", nrow(rtdata$features[rtdata$features$lipidname_final == "", ]),
                     "\n|-----------------------------------------------------------------\n",
                     " =================================================================\n")

  }


  for (lipidclass in names(models)) {
    model_info <- models[[lipidclass]]
    model <- model_info$model
    metrics <- model_info$metrics

    report <- paste0(report,
                     "\n=================================================================\n",
                     "Lipid class: ", lipidclass, "\n",
                     "=================================================================\n",
                     "Model summary:\n",
                     paste(capture.output(summary(model)), collapse = "\n"),
                     "\n\nMetrics:",
                     "\n-----------\n",
                     sprintf("AIC: %.2f\n", metrics$AIC),
                     sprintf("logLik: %.2f\n", metrics$logLik),
                     sprintf("RMSE: %.4f\n", metrics$RMSE),
                     sprintf("PseudoR2: %.4f\n", metrics$pseudoR2),
                     "\n------------------------------------------------------------------\n")
  }

  if (is.null(file_path)) {
    return(report)
  } else {
    # Save
    writeLines(report, file_path)
    cat("Report file saved:", file_path, "\n")
  }

}
